using System;
using System.IO;
using System.Linq;
using PeerChatDesktop;

class ProfileManagerTest {
    static void Require(bool condition,string message){if(!condition)throw new Exception(message);}
    static void DiagnosticsRetentionTests(string root){
        var attempts=new ConnectionAttemptTracker();
        var progress=attempts.Update(new CoreEvent{kind=16,peer="peer-one",expected="peer-one",text="relay rendezvous established; peer TLS begins"},null);
        Require(progress.LatestProgress.Contains("peer TLS begins")&&progress.LatestFailure=="None","Normal relay/TLS progress was mislabeled as a failed attempt");
        var failed=attempts.Update(new CoreEvent{kind=8,peer="peer-one",expected="peer-one",text="peer TLS failed"},null);
        Require(failed.LatestFailure=="peer TLS failed"&&failed.LatestProgress.Contains("peer TLS begins"),"Failure and progress diagnostics were not kept separate");
        int collected=0;var service=new DiagnosticsService(new DiagnosticsSources{Connection=()=>{collected++;return "route=PeerChat Server Relay";},ConnectionEvents=()=>"connected",Security=()=>"TLS verified",Voice=()=>"voice idle",ScreenShare=()=>"h264_sender_sps=2\nmedia_failure_domain=local_encoder",Local=()=>"profile test",Status=()=>"Ready",Build=()=>"test-build",Profile=()=>"test-profile"});
        var snapshot=service.Capture();Require(collected==1&&snapshot.Sections.Count==6,"Diagnostics service did not collect the subsystem snapshots through one provider");Require(DiagnosticsService.FormatFull(snapshot).Contains("h264_sender_sps=2"),"Full formatting omitted existing detailed screen diagnostics");
        var failure=service.FreezeFailure("Screen share stopped — Encoder Error","ScreenShare","share-a","local_encoder","encoder failed","first encoder input",7,snapshot);failure.Module="PeerChat.ScreenMedia.dll";string storePath=Path.Combine(root,"diagnostic-retention");var store=new DiagnosticsRetentionStore(storePath);store.AddFailure(failure);snapshot.Sections[5].Details="overwritten after teardown";Require(store.Failures().Single().Diagnostics.Sections.Any(section=>section.Details=="profile test"),"Frozen diagnostics changed after the source snapshot was reset");
        for(int index=0;index<18;index++){var item=service.FreezeFailure("Failure "+index,"Connection",index.ToString(),"transport","reason","connect",index,service.Capture());store.AddFailure(item);}Require(store.Failures().Count==15,"Recent failure history was not bounded to 15 records");
        store.UpdateOperation(new ActiveDiagnosticOperation{OperationType="Voice",OperationId="clean-call",Stage="connected",Generation=2,Diagnostics=service.Capture()});store.CompleteOperation("Voice","clean-call");Require(store.RecoverUncleanOperations("test-build").Count==0,"Clean operation completion was reported as an unclean crash");
        store.UpdateOperation(new ActiveDiagnosticOperation{OperationType="ScreenShare",OperationId="unclean-share",Stage="capture started",Generation=4,Module="PeerChat.ScreenMedia.dll",Diagnostics=service.Capture()});var recovered=new DiagnosticsRetentionStore(storePath).RecoverUncleanOperations("test-build");Require(recovered.Count==1&&recovered[0].FailureDomain=="process_exit"&&recovered[0].Stage=="capture started"&&recovered[0].Module=="PeerChat.ScreenMedia.dll","Unfinished active operation was not retained with module/build context");Require(new DiagnosticsRetentionStore(storePath).RecoverUncleanOperations("test-build").Count==0,"Unclean operation marker was not cleared after recovery");
        string filtered=DiagnosticsPrivacyFilter.Redact("turn_password=do-not-store\nauth_token=secret\nmessage_content=private text\nPeer ID=public-safe");Require(!filtered.Contains("do-not-store")&&!filtered.Contains("private text")&&filtered.Contains("public-safe"),"Diagnostic privacy filter retained sensitive values or removed safe identifiers");
        var grouped=new DiagnosticsSnapshot{Profile="test-profile",Sections=new System.Collections.Generic.List<DiagnosticsSection>{new DiagnosticsSection{Name="Connection",Details="Account ID: 7\nConversation ID: account:7\nExpected Peer ID: aaaa"},new DiagnosticsSection{Name="Connection events",Details="2026-01-01T00:00:00Z stage=connected account=7 conversation=account:7 expected_peer=aaaa current_peer=aaaa candidate=relay-a\n2026-01-01T00:00:01Z stage=connected account=8 conversation=account:8 expected_peer=bbbb current_peer=bbbb candidate=relay-b"},new DiagnosticsSection{Name="Voice",Details="expected_peer_id=aaaa\ncall_id=voice-a"},new DiagnosticsSection{Name="Screen share",Details="expected_peer_id=bbbb\nshare_id=share-b"}}};
        var scopes=DiagnosticsService.ConnectionScopes(grouped);Require(scopes.Count==2,"Diagnostics did not identify the two logical peer sessions");var firstScope=scopes.Single(scope=>scope.RemotePeerId=="aaaa");string firstProjection=DiagnosticsService.FormatFull(DiagnosticsService.ProjectConnection(grouped,firstScope,"Overview"));Require(firstProjection.Contains("voice-a")&&!firstProjection.Contains("share-b")&&!firstProjection.Contains("relay-b"),"Diagnostics connection projection mixed peer/session state or grouped by a temporary route");
        Func<string,string> sameName=id=>id=="7"||id=="8"?"Jonah":"";var friendlyScopes=DiagnosticsService.ConnectionScopes(grouped,sameName);var friendlyFirst=friendlyScopes.Single(scope=>scope.RemotePeerId=="aaaa");var friendlySecond=friendlyScopes.Single(scope=>scope.RemotePeerId=="bbbb");Require(friendlyFirst.Label.StartsWith("Jonah:7",StringComparison.Ordinal)&&friendlyFirst.ConversationId=="account:7"&&friendlyFirst.Key.Contains("|7|account:7|"),"Known username was not presentation-only or canonical account key changed");Require(friendlySecond.Label.StartsWith("Jonah:8",StringComparison.Ordinal)&&friendlyFirst.Key!=friendlySecond.Key,"Same display name caused logical accounts to collide");var fallback=DiagnosticsService.ConnectionScopes(grouped,id=>"").Single(scope=>scope.RemotePeerId=="aaaa");Require(fallback.Label.StartsWith("account:7",StringComparison.Ordinal),"Unknown username did not retain canonical account label fallback");
        string formatted=DiagnosticsService.FormatFull(grouped,sameName,peer=>peer=="aaaa"?"Jonah:7":"Jonah:8");Require(formatted.Contains("Account: Jonah:7")&&formatted.Contains("Conversation: Jonah:7")&&formatted.Contains("account=Jonah:8 conversation=Jonah:8"),"Full diagnostics did not present friendly account/session labels");Require(grouped.Sections[0].Details.Contains("account:7")&&grouped.Sections[1].Details.Contains("account=8 conversation=account:8"),"Display formatting mutated canonical diagnostic snapshot identity");
        string summary=DiagnosticsService.FormatSummary(grouped,sameName,peer=>"Jonah:7");Require(summary.Contains("Account: Jonah:7")&&summary.Contains("Conversation: Jonah:7"),"Copied summary omitted friendly account/session labels");var retained=service.FreezeFailure("Failure","Connection","a","transport","reason","connect",1,grouped);Require(DiagnosticsService.FormatFailureFull(retained,sameName,peer=>"Jonah:7").Contains("Conversation: Jonah:7")&&DiagnosticsService.FormatFailureSummary(retained,sameName,peer=>"Jonah:7").Contains("Conversation: Jonah:7"),"Retained failure formatting omitted friendly labels");
        var accountNineteen=new DiagnosticsSnapshot{Profile="test-profile",Sections=new System.Collections.Generic.List<DiagnosticsSection>{new DiagnosticsSection{Name="Connection",Details="Account ID: 19\nConversation ID: account:19\nExpected Peer ID: peer-19"}}};var nineteen=DiagnosticsService.ConnectionScopes(accountNineteen,id=>id=="19"?"Jonah":"").Single();Require(nineteen.Label.StartsWith("Jonah:19",StringComparison.Ordinal)&&nineteen.ConversationId=="account:19"&&nineteen.Key.Contains("|19|account:19|"),"Known account:19 was not displayed as Jonah:19 without changing its canonical key");
        var groupSnapshot=new DiagnosticsSnapshot{Profile="test-profile",Sections=new System.Collections.Generic.List<DiagnosticsSection>{new DiagnosticsSection{Name="Connection events",Details="2026-01-01T00:00:01Z stage=connected account=7 conversation=account:7 expected_peer=aaaa candidate=relay-a"},new DiagnosticsSection{Name="Voice",Details="expected_peer_id=aaaa\ncall_id=one-to-one-call"},new DiagnosticsSection{Name="Screen share",Details="expected_peer_id=aaaa\nshare_id=one-to-one-share"}},Groups=new System.Collections.Generic.List<GroupDiagnosticsData>{new GroupDiagnosticsData{GroupId="11111111111111111111111111111111",Name="Gaming Group",LocalRole="Owner",RosterState="Ready",GroupControlState="Not established",E2eeState="Group content encryption not active",PendingInvites=1,Members=new System.Collections.Generic.List<GroupDiagnosticsMember>{new GroupDiagnosticsMember{AccountId=7,Name="Jonah",PeerId="aaaa",Role="Member",Relationship="Friend"},new GroupDiagnosticsMember{AccountId=8,Name="Sammy",PeerId="bbbb",Role="Member",Relationship="None"}}},new GroupDiagnosticsData{GroupId="22222222222222222222222222222222",Name="Other Group",Members=new System.Collections.Generic.List<GroupDiagnosticsMember>()}}};
        Require(DiagnosticsService.GroupScopes(groupSnapshot).Count==2,"Groups were not first-class diagnostics targets");
        Require(DiagnosticsService.FormatFull(groupSnapshot).Contains("Gaming Group")&&DiagnosticsService.FormatFull(groupSnapshot).Contains("Other Group"),"Full diagnostics omitted structured group targets");
        var groupOverview=DiagnosticsService.FormatFull(DiagnosticsService.ProjectGroup(groupSnapshot,"11111111111111111111111111111111","Overview"));
        Require(groupOverview.Contains("Type: Group")&&groupOverview.Contains("Gaming Group")&&groupOverview.Contains("Member count: 2")&&!groupOverview.Contains("Other Group")&&!groupOverview.Contains("one-to-one-call"),"Group overview mixed targets or one-to-one media");
        var groupConnection=DiagnosticsService.FormatFull(DiagnosticsService.ProjectGroup(groupSnapshot,"11111111111111111111111111111111","Connection"));
        Require(groupConnection.Contains("Server group roster: Ready")&&groupConnection.Contains("Jonah")&&groupConnection.Contains("Sammy")&&groupConnection.Contains("not proof of GroupControl")&&!groupConnection.Contains("relay-a"),"Group connection invented a single route or leaked peer event details");
        Require(DiagnosticsService.FormatFull(DiagnosticsService.ProjectGroup(groupSnapshot,"11111111111111111111111111111111","Voice")).Contains("Voice room: Inactive")&&!DiagnosticsService.FormatFull(DiagnosticsService.ProjectGroup(groupSnapshot,"11111111111111111111111111111111","Voice")).Contains("one-to-one-call"),"Group voice reused one-to-one VoiceMedia state");
        groupSnapshot.Groups[0].RoomVoiceState="Voice room: Active\nLocal participation: Joined\nParticipant count: 1";
        string liveGroupVoice=DiagnosticsService.FormatFull(DiagnosticsService.ProjectGroup(groupSnapshot,"11111111111111111111111111111111","Voice"));
        Require(liveGroupVoice.Contains("Participant count: 1")&&liveGroupVoice.Contains("Local participation: Joined")&&!liveGroupVoice.Contains("Not implemented")&&!liveGroupVoice.Contains("one-to-one-call"),"Live group voice did not use its own authoritative snapshot");
        Require(DiagnosticsService.FormatFull(DiagnosticsService.ProjectGroup(groupSnapshot,"11111111111111111111111111111111","Screen Share")).Contains("Screen share: Inactive")&&!DiagnosticsService.FormatFull(DiagnosticsService.ProjectGroup(groupSnapshot,"11111111111111111111111111111111","Screen Share")).Contains("one-to-one-share"),"Group screen share reused one-to-one media state");
        var frozenGroup=DiagnosticsService.Clone(groupSnapshot);groupSnapshot.Groups[0].Name="changed";Require(frozenGroup.Groups[0].Name=="Gaming Group","Frozen group diagnostics were mutated after capture");
        var groupFailure=service.FreezeFailure("Group relay failed","GroupControl","11111111111111111111111111111111","relay","unavailable","reconnect",3,frozenGroup);store.AddFailure(groupFailure);Require(store.Failures().First().Diagnostics.Groups[0].Name=="Gaming Group","Retained group diagnostics were not preserved as immutable structured data");
    }
    static int Main(){try{
        string root=Path.Combine(Environment.CurrentDirectory,"build","tests","runtime","profiles-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);DiagnosticsRetentionTests(root);
        byte[] encryptedHistory={1,7,3,9,11,42};File.WriteAllBytes(Path.Combine(root,"peerchat.sqlite"),encryptedHistory);File.WriteAllBytes(Path.Combine(root,"discovery-session.dat"),new byte[]{8,6,4,2});
        var manager=new LocalProfileManager(root);var first=manager.Initialize();var a=first.Profiles.Single();Require(a.MigratedLegacy,"Legacy profile was not migrated");Require(File.ReadAllBytes(Path.Combine(manager.ProfilePath(a.Id),"peerchat.sqlite")).SequenceEqual(encryptedHistory),"Legacy encrypted history bytes changed");Require(File.Exists(Path.Combine(root,"peerchat.sqlite")),"Legacy source was not retained");
        var secondPass=manager.Initialize();Require(secondPass.Profiles.Count==1&&secondPass.Profiles[0].Id==a.Id,"Migration was not idempotent");File.WriteAllText(Path.Combine(manager.ProfilePath(a.Id),"a-history.marker"),"A only");File.WriteAllText(Path.Combine(manager.ProfilePath(a.Id),"a-trust.marker"),"A only");
        var b=manager.Create("Profile B");Require(a.Id!=b.Id,"Stable profiles reused an ID");Require(!File.Exists(Path.Combine(manager.ProfilePath(b.Id),"a-history.marker"))&&!File.Exists(Path.Combine(manager.ProfilePath(b.Id),"a-trust.marker")),"A state appeared in B");
        manager.Select(a.Id);Require(manager.Selected().Id==a.Id,"Selector did not choose A");manager.Select(b.Id);Require(manager.Selected().Id==b.Id,"Selector did not choose B");manager.Select(a.Id);Require(File.Exists(Path.Combine(manager.ProfilePath(a.Id),"a-history.marker")),"A-B-A switch did not restore A path");
        manager.Select(b.Id);string bPath=manager.ProfilePath(b.Id);File.WriteAllText(Path.Combine(bPath,"identity.marker"),"B identity");File.WriteAllText(Path.Combine(bPath,"stale-route.marker"),"stale");File.WriteAllText(Path.Combine(bPath,"peerchat.sqlite-wal"),"runtime");File.WriteAllText(Path.Combine(bPath,"peerchat.sqlite-shm"),"runtime");File.WriteAllText(Path.Combine(bPath,".peerchat-profile.lock"),"runtime");
        string backup=Path.Combine(root,"backup");var backupRequest=manager.CreateMaintenanceRequest(ProfileMaintenanceAction.Backup,b.Id,backup);manager.ExecuteMaintenance(backupRequest,(oldPath,newPath)=>"peer-b");manager.CompleteMaintenanceRequest(backupRequest);Require(File.Exists(Path.Combine(backup,"profile-metadata.json")),"Backup metadata was not written");Require(File.ReadAllText(Path.Combine(backup,"profile-metadata.json")).Contains("peer-b"),"Backup metadata omitted the safe device Peer ID");Require(File.Exists(Path.Combine(backup,"PeerChatProfile","identity.marker")),"Backup B failed");Require(!File.Exists(Path.Combine(backup,"PeerChatProfile",".peerchat-profile.lock"))&&!File.Exists(Path.Combine(backup,"PeerChatProfile","peerchat.sqlite-wal"))&&!File.Exists(Path.Combine(backup,"PeerChatProfile","peerchat.sqlite-shm")),"Backup retained runtime SQLite/lock files");
        string lockedRecovery=Path.Combine(root,"locked-reset");var lockedRequest=manager.CreateMaintenanceRequest(ProfileMaintenanceAction.Reset,b.Id,lockedRecovery);using(var held=LocalProfileLease.TryAcquire(bPath)){Require(held!=null,"Test could not acquire profile lock");bool rejected=false;try{manager.ExecuteMaintenance(lockedRequest,(oldPath,newPath)=>"peer-b");}catch(InvalidOperationException error){rejected=error.Message.Contains("currently open in another PeerChat process");}Require(rejected,"Active profile maintenance did not reject a held lock");}manager.CompleteMaintenanceRequest(lockedRequest);
        string reset=Path.Combine(root,"reset");var resetRequest=manager.CreateMaintenanceRequest(ProfileMaintenanceAction.Reset,b.Id,reset);manager.ExecuteMaintenance(resetRequest,(oldPath,newPath)=>{File.WriteAllText(Path.Combine(newPath,"identity.marker"),"B identity preserved");return "peer-b";});manager.CompleteMaintenanceRequest(resetRequest);Require(File.ReadAllText(Path.Combine(bPath,"identity.marker"))=="B identity preserved","Reset did not rebuild the preserved device identity");Require(!File.Exists(Path.Combine(bPath,"stale-route.marker"))&&!File.Exists(Path.Combine(bPath,"peerchat.sqlite-wal")),"Reset retained stale local runtime state");Require(File.Exists(Path.Combine(reset,"PeerChatProfile-reset-recovery","stale-route.marker")),"Reset did not retain a recovery copy");Require(File.Exists(Path.Combine(manager.ProfilePath(a.Id),"a-history.marker")),"Reset B changed A");
        File.WriteAllText(Path.Combine(bPath,"mutation.marker"),"mutated");string safety=Path.Combine(root,"safety");var restoreRequest=manager.CreateMaintenanceRequest(ProfileMaintenanceAction.Restore,b.Id,safety,backup);manager.ExecuteMaintenance(restoreRequest,(oldPath,newPath)=>"unused");manager.CompleteMaintenanceRequest(restoreRequest);Require(File.ReadAllText(Path.Combine(bPath,"identity.marker"))=="B identity","Restore B failed");Require(!File.Exists(Path.Combine(bPath,"mutation.marker")),"Restore retained changed profile state");Require(File.Exists(Path.Combine(safety,"PeerChatProfile-pre-restore","mutation.marker")),"Restore did not retain its rollback copy");Require(File.Exists(Path.Combine(manager.ProfilePath(a.Id),"a-trust.marker")),"Restore B changed A");
        manager.Rename(b.Id,"Renamed B");Require(manager.Selected().Name=="Renamed B","Rename did not update the selected card");manager.Remove(a.Id);Require(manager.Load().Profiles.Count==1&&Directory.Exists(Path.Combine(root,"RemovedProfiles")),"Confirmed local-profile removal was not isolated/recoverable");
        Console.WriteLine("PASS: profile catalog, idempotent verified legacy copy, selector path, A/B isolation, encrypted reliable-P2P preferences, switch, reset, restore, rename, recoverable remove, unified diagnostic collection, immutable failure retention, crash marker recovery, privacy filter, and bounded history.");return 0;
    }catch(Exception error){Console.Error.WriteLine("FAIL: "+error);return 1;}}
}
